import base64,json,hashlib,subprocess,os,datetime
from pathlib import Path
r=Path('/tmp/zhixin_paper2_pilot0_20261102_r01')
assert not (r/'parallel_authorization.json').exists(), 'Already changed; inspect state instead of repeating'
q=subprocess.check_output(['squeue','-h','-j','19160,19161','-o','%i|%T|%R'],text=True)
assert '19161|PENDING|(Dependency)' in q and '19160|RUNNING|' in q
assert not (r/'M1/started.json').exists()
cpus=subprocess.check_output(['sinfo','-h','-p','debug','-o','%C'],text=True).strip()
assert int(cpus.split('/')[1])>=2
available=int(next(x for x in Path('/proc/meminfo').read_text().splitlines() if x.startswith('MemAvailable:')).split()[1])*1024
assert available>=16*1024**3
st=os.statvfs(r);assert st.f_bavail*st.f_frsize>=8*1024**3
for role in ('M0','M1'):
 p=json.loads((r/role/'plan.json').read_text())
 assert hashlib.sha256((r/role/'params.input').read_bytes()).hexdigest()==p['input_sha256']
original=(r/'pilot0_sal_worker.py').read_bytes();assert hashlib.sha256(original).hexdigest()=='ba42f3f28723a67169cc462663c5060281fec6782dfa41ca393409af79c791d4'
worker=base64.b64decode('');compile(worker,'parallel_worker','exec')
(r/'pilot0_sal_worker.before_parallel.py').write_bytes(original)
(r/'pilot0_sal_worker.parallel.tmp').write_bytes(worker)
(r/'pilot0_sal_worker.parallel.tmp').replace(r/'pilot0_sal_worker.py')
record=dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),allow_parallel_pair=True,M0_job_id='19160',M1_job_id='19161',user_instruction='M0 and M1 each use one core concurrently; check resources first; analyze and report after completion',resources=dict(cpu_allocation=cpus,available_memory_bytes=available,scratch_available_bytes=st.f_bavail*st.f_frsize),old_worker_sha256='ba42f3f28723a67169cc462663c5060281fec6782dfa41ca393409af79c791d4',new_worker_sha256=hashlib.sha256(worker).hexdigest(),M0_running_original_worker_unchanged=True,final_analysis_requires_complete_M0_bridge_and_M1_initial_check=True)
(r/'parallel_authorization.json').write_text(json.dumps(record,indent=2)+'\n')
change=subprocess.run(['scontrol','update','JobId=19161','Dependency='],capture_output=True,text=True)
record['scontrol']=dict(returncode=change.returncode,stdout=change.stdout,stderr=change.stderr)
record['job_after']=subprocess.check_output(['scontrol','show','job','19161'],text=True)
(r/'parallel_activation.json').write_text(json.dumps(record,indent=2)+'\n')
if change.returncode==0:
 jobs=json.loads((r/'slurm_jobs.json').read_text());(r/'slurm_jobs.before_parallel.json').write_text(json.dumps(jobs,indent=2)+'\n')
 jobs['policy']='User-authorized M0/M1 concurrent, one physical core and one rank each, each <=12h; final analysis gates retained'
 (r/'slurm_jobs.json').write_text(json.dumps(jobs,indent=2)+'\n')
 record['jobs']=jobs
print(json.dumps(record))
